def text(node, *names):
    for name in names:
        found = node.find(name)
        if found is not None and found.text:
            return found.text.strip()
    return ""

def clean_title(title):
    return re.sub(r"\s+", " ", title).strip()[:240]

def clean_summary(value):
    if not value:
        return ""
    value = unescape(value)
    value = re.sub(r"<[^>]+>", " ", value)
    value = re.sub(r"\s+", " ", value).strip()
    # RSS feeds sometimes append publisher boilerplate that adds no editorial value.
    value = re.sub(r"\s*The post .+? appeared first on The GitHub Blog\s*\.?$", "", value, flags=re.I)
    value = re.sub(r"\s+", " ", value).strip()
    return value[:900]

def load_model_pricing_catalog():
    data = json.loads(MODEL_PRICING_PATH.read_text(encoding="utf-8"))
    models = data.get("models")
    if not isinstance(models, list) or not models:
        raise RuntimeError("model-pricing.json must contain a non-empty models array")
    by_id = {}
    for model in models:
        model_id = model.get("model_id")
        if not model_id or model_id in by_id:
            raise RuntimeError(f"Invalid or duplicate model_id in model-pricing.json: {model_id}")
        by_id[model_id] = model
    return data, by_id


MODEL_PRICING_CATALOG, MODEL_PRICING_BY_ID = load_model_pricing_catalog()


def load_model_comparisons():
    data = json.loads(MODEL_COMPARISONS_PATH.read_text(encoding="utf-8"))
    comparisons = data.get("comparisons")
    if not isinstance(comparisons, list) or not comparisons:
        raise RuntimeError("model-comparisons.json must contain a non-empty comparisons array")
    by_slug = {}
    for comparison in comparisons:
        slug = comparison.get("slug")
        if not slug or slug in by_slug:
            raise RuntimeError(f"Invalid or duplicate comparison slug: {slug}")
        by_slug[slug] = comparison
    return data, by_slug


