def compact_token_count(value):
    if value == "unlimited":
        return "No separate limit"
    if value is None:
        return "Not published"
    value = int(value)
    if value >= 1_000_000:
        rendered = f"{value / 1_000_000:.3f}".rstrip("0").rstrip(".")
        return f"{rendered}M tokens"
    if value >= 1_000:
        rendered = f"{value / 1_000:.1f}".rstrip("0").rstrip(".")
        return f"{rendered}K tokens"
    return f"{value:,} tokens"


def percent_delta(before, after):
    if not isinstance(before, (int, float)) or not isinstance(after, (int, float)):
        return None
    if before == 0:
        return None
    return (after - before) / before * 100


def percent_delta_label(before, after):
    delta = percent_delta(before, after)
    if delta is None:
        return ""
    rendered = f"{abs(delta):.1f}".rstrip("0").rstrip(".")
    sign = "+" if delta > 0 else "−" if delta < 0 else "±"
    return f"{sign}{rendered}%"


def pricing_period_from_snapshot(pricing, on_date):
    schedule = pricing.get("standard", []) if isinstance(pricing, dict) else []
    if not schedule:
        return {}
    target = datetime.fromisoformat(on_date).date() if isinstance(on_date, str) else on_date
    for period in schedule:
        try:
            start = datetime.fromisoformat(period["start"]).date()
            end = datetime.fromisoformat(period["end"]).date() if period.get("end") else None
        except Exception:
            continue
        if target >= start and (end is None or target <= end):
            return period
    return schedule[-1]


def summarize_collection(value):
    if isinstance(value, list):
        return ", ".join(str(item) for item in value) or "none"
    if isinstance(value, dict):
        parts = []
        for key, item in value.items():
            label = key.replace("_", " ")
            if isinstance(item, list):
                parts.append(f"{label}: {', '.join(str(x) for x in item)}")
            elif isinstance(item, (str, int, float, bool)):
                parts.append(f"{label}: {item}")
        return " · ".join(parts[:5]) or "configuration"
    if value is None:
        return "not listed"
    return str(value)


def change_delta_items(change, verified_at):
    field = change.get("field")
    before = change.get("before")
    after = change.get("after")
    items = []

    if field in {"context_window", "max_output"}:
        label = "Context window" if field == "context_window" else "Max output"
        delta = percent_delta_label(before, after)
        items.append({
            "label": label,
            "before": compact_token_count(before),
            "after": compact_token_count(after),
            "delta": delta,
        })
        return items

    if field == "pricing":
        old_period = pricing_period_from_snapshot(before or {}, verified_at)
        new_period = pricing_period_from_snapshot(after or {}, verified_at)
        labels = {
            "input": "Input / MTok",
            "cached_input": "Cached input / MTok",
            "cache_write": "Cache write / MTok",
            "cache_write_5m": "5m cache write / MTok",
            "cache_write_1h": "1h cache write / MTok",
            "output": "Output / MTok",
        }
        for key, label in labels.items():
            old = old_period.get(key)
            new = new_period.get(key)
            if old is None and new is None:
                continue
            if old == new:
                continue
            items.append({
                "label": label,
                "before": catalog_price_label(old) if old is not None else "—",
                "after": catalog_price_label(new) if new is not None else "—",
                "delta": percent_delta_label(old, new),
            })
        if not items:
            old_schedule = (before or {}).get("standard", [])
            new_schedule = (after or {}).get("standard", [])
            old_next = old_schedule[-1].get("start") if old_schedule else "—"
            new_next = new_schedule[-1].get("start") if new_schedule else "—"
            items.append({
                "label": "Pricing schedule",
                "before": old_next,
                "after": new_next,
                "delta": "",
            })
        return items

    if field == "knowledge_cutoff":
        return [{"label": "Knowledge cutoff", "before": summarize_collection(before), "after": summarize_collection(after), "delta": ""}]

    if field == "status":
        return [{"label": "Model status", "before": summarize_collection(before), "after": summarize_collection(after), "delta": ""}]

    if field == "availability":
        return [{"label": "Availability", "before": summarize_collection(before), "after": summarize_collection(after), "delta": ""}]

    if field == "modalities":
        return [{"label": "Modalities", "before": summarize_collection(before), "after": summarize_collection(after), "delta": ""}]

    if field == "reasoning":
        return [{"label": "Reasoning controls", "before": summarize_collection(before), "after": summarize_collection(after), "delta": ""}]

    if field in {"provider", "family", "model", "aliases"}:
        return [{"label": field.replace("_", " ").title(), "before": summarize_collection(before), "after": summarize_collection(after), "delta": ""}]

    return [{"label": field.replace("_", " ").title(), "before": summarize_collection(before), "after": summarize_collection(after), "delta": ""}]


def change_event_items(event):
    result = []
    for change in event.get("changes", []):
        for item in change_delta_items(change, event["verified_at"]):
            result.append({
                **item,
                "change_type": change.get("change_type", "model_change"),
                "source_url": change.get("source_url", ""),
            })
    return result


def change_event_summary(event):
    items = change_event_items(event)
    if not items:
        return "Verified model facts changed."
    chunks = []
    for item in items[:4]:
        text_value = f'{item["label"]}: {item["before"]} → {item["after"]}'
        if item.get("delta"):
            text_value += f' ({item["delta"]})'
        chunks.append(text_value)
    if len(items) > 4:
        chunks.append(f"+{len(items) - 4} more")
    return " · ".join(chunks)


def model_change_watch_html(model_ids, heading="What changed"):
    history = load_model_history()
    wanted = set(model_ids)
    all_events = [event for event in history["events"] if event.get("model_id") in wanted]
    changes = [event for event in all_events if event.get("type") == "model_changed"]
    baseline_dates = [event["verified_at"] for event in all_events if event.get("type") in {"baseline", "model_added"}]
    baseline = min(baseline_dates) if baseline_dates else history.get("baseline_verified_at", MODEL_PRICING_CATALOG["source_verified"])

    if not changes:
        model_names = [MODEL_PRICING_BY_ID[mid]["model"] for mid in model_ids if mid in MODEL_PRICING_BY_ID]
        names = ", ".join(model_names)
        return f'''<section class="model-change-watch shell" data-what-changed data-change-count="0" data-change-models="{escape(",".join(model_ids), quote=True)}">
          <div class="change-watch-empty"><div><p class="eyebrow">WHAT CHANGED</p><h2>{escape(heading)}</h2><p>No post-baseline factual changes recorded for {escape(names)} since {escape(baseline)}.</p></div>
          <div class="change-watch-status"><span>VERIFIED BASELINE</span><strong>{escape(baseline)}</strong><small>Current facts remain aligned with the SXF ledger.</small></div></div>
        </section>'''

    cards = []
    for event in reversed(changes[-6:]):
        model = MODEL_PRICING_BY_ID.get(event["model_id"], {})
        items = change_event_items(event)
        item_html = "".join(
            f'''<div class="change-delta" data-change-type="{escape(item["change_type"], quote=True)}">
              <span>{escape(item["label"])}</span>
              <div><del>{escape(item["before"])}</del><b>→</b><ins>{escape(item["after"])}</ins>{f'<em>{escape(item["delta"])}</em>' if item.get("delta") else ""}</div>
            </div>'''
            for item in items
        )
        source = next((item.get("source_url") for item in items if item.get("source_url")), model.get("official_sources", [""])[0])
        cards.append(
            f'''<article class="change-watch-card" data-change-event="{escape(event["event_id"], quote=True)}" data-model-id="{escape(event["model_id"], quote=True)}">
              <div class="change-watch-meta"><span>{escape(model.get("model", event["model_id"]))}</span><time datetime="{escape(event["verified_at"], quote=True)}">{escape(event["verified_at"])}</time></div>
              <div class="change-deltas">{item_html}</div>
              <a href="{escape(source, quote=True)}" target="_blank" rel="noopener noreferrer">Verify at official source ↗</a>
            </article>'''
        )

    return f'''<section class="model-change-watch shell" data-what-changed data-change-count="{len(changes)}" data-change-models="{escape(",".join(model_ids), quote=True)}">
      <div class="intel-section-head"><div><p class="eyebrow">WHAT CHANGED</p><h2>{escape(heading)}</h2></div><span>{len(changes)} verified change{"s" if len(changes) != 1 else ""} since {escape(baseline)}</span></div>
      <div class="change-watch-grid">{"".join(cards)}</div>
      <div class="compare-live-foot"><span>Only source-backed factual changes enter this view.</span><a href="/data/model-history.json">Open full ledger ↗</a></div>
    </section>'''


def compare_change_watch_html(model_ids):
    names = [MODEL_PRICING_BY_ID[mid]["model"] for mid in model_ids if mid in MODEL_PRICING_BY_ID]
    return model_change_watch_html(model_ids, "Changes affecting this comparison.")


def model_output_label(model):
    value = model.get("max_output")
    if value == "unlimited":
        return "No separate limit"
    if value is None:
        return "Not published"
    return f"{int(value):,}"


def model_reasoning_label(model):
    reasoning = model.get("reasoning")
    if not isinstance(reasoning, dict):
        return "Not published"
    levels = [str(level) for level in reasoning.get("levels", []) if level is not None]
    label = " · ".join(levels) if levels else str(reasoning.get("type") or "Published")
    default = reasoning.get("default")
    if default:
        label += f" · default {default}"
    return label


def catalog_owns_model_route(name):
    for model in MODEL_PRICING_CATALOG["models"]:
        if model.get("model", "").lower() != name.lower():
            continue
        return model.get("sxf_url") == f"/models/{slugify(name)}/"
    return False


def model_history_html(model_ids, heading="Verified model history"):
    if not model_ids:
        return ""
    history = load_model_history()
    events = [event for event in history["events"] if event.get("model_id") in set(model_ids)]
    if not events:
        return ""

    latest_by_model = {}
    for event in events:
        latest_by_model[event["model_id"]] = event
    selected = list(events[-12:])
    selected_ids = {event["event_id"] for event in selected}
    for event in latest_by_model.values():
        if event["event_id"] not in selected_ids:
            selected.append(event)
    selected.sort(key=lambda event: event["sequence"], reverse=True)

    rows = []
    for event in selected:
        model = MODEL_PRICING_BY_ID.get(event["model_id"], {})
        model_name = model.get("model", event["model_id"])
        if event["type"] in {"baseline", "model_added"}:
            snapshot = event.get("snapshot", {})
            price = (snapshot.get("pricing", {}).get("standard") or [{}])[-1]
            context = snapshot.get("context_window")
            context_label = "context not published" if context is None else f"{int(context):,} context"
            summary = f'Baseline verified: {context_label} · {model_output_label(snapshot)} max output'
            basis = model.get("pricing_basis", {})
            meter = basis.get("meter")
            display_unit = basis.get("display_unit", "")
            if meter == "tokens":
                token_parts = []
                if price.get("input") is not None:
                    token_parts.append(f'{catalog_price_label(price["input"])} input')
                if price.get("cached_input") is not None:
                    token_parts.append(f'{catalog_price_label(price["cached_input"])} cached')
                if price.get("output") is not None:
                    token_parts.append(f'{catalog_price_label(price["output"])} output')
                if token_parts:
                    summary += f' · {" / ".join(token_parts)} {display_unit}'.rstrip()
            else:
                dimensions = basis.get("dimensions", [])
                rates = price.get("rates", {})
                if dimensions and rates.get(dimensions[0]) is not None:
                    summary += f' · {catalog_price_label(rates[dimensions[0]])} {display_unit}'.rstrip()
            source = event.get("evidence", {}).get("model_identity") or model.get("official_sources", [""])[0]
            kind = "BASELINE"
        else:
            changes = event.get("changes", [])
            summary = change_event_summary(event)
            source = changes[0]["source_url"] if changes else model.get("official_sources", [""])[0]
            kind = "CHANGE"

        rows.append(
            f'''<article class="model-history-event" data-history-event="{escape(event["event_id"], quote=True)}" data-model-id="{escape(event["model_id"], quote=True)}">
              <div class="model-history-meta"><span>{kind}</span><time datetime="{escape(event["verified_at"], quote=True)}">{escape(event["verified_at"])}</time></div>
              <h3>{escape(model_name)}</h3><p>{escape(summary)}</p>
              <a href="{escape(source, quote=True)}" target="_blank" rel="noopener noreferrer">Official evidence ↗</a>
            </article>'''
        )

    return f'''<section class="model-history shell" data-model-history data-history-models="{escape(",".join(model_ids), quote=True)}">
      <div class="intel-section-head"><div><p class="eyebrow">VERIFIED CHANGE HISTORY</p><h2>{escape(heading)}</h2></div><a href="/data/model-history.json">Open ledger JSON ↗</a></div>
      <div class="model-history-grid">{"".join(rows)}</div>
      <p class="reference-note">Append-only SXF ledger · {len(events)} verified event{"s" if len(events) != 1 else ""} · chain head {escape(history.get("chain_head", "")[:12])}…</p>
    </section>'''


def comparison_price_snapshot(model_id, on_date=None):
    model = model_catalog_entry(model_id)
    if not model_has_official_paid_pricing(model):
        return None
    return active_standard_price(model_id, on_date or MODEL_PRICING_CATALOG["source_verified"])


def comparison_price_text(model_id, on_date=None):
    model = model_catalog_entry(model_id)
    price = comparison_price_snapshot(model_id, on_date)
    if not price:
        return model_pricing_status(model)
    return f'{catalog_price_label(price["input"])}/{catalog_price_label(price["output"])}'


def compare_live_facts_html(model_ids):
    verified = MODEL_PRICING_CATALOG["source_verified"]
    cards = []
    for model_id in model_ids:
        model = model_catalog_entry(model_id)
        price = comparison_price_snapshot(model_id, verified)
        evidence = model["provenance"]["evidence"]
        modalities = " + ".join(model.get("modalities", {}).get("input", [])) or "Not published"
        input_price = catalog_price_label(price["input"]) if price else "Not published"
        cached_price = catalog_price_label(price.get("cached_input")) if price and price.get("cached_input") is not None else "—"
        output_price = catalog_price_label(price["output"]) if price else "Not published"
        cards.append(
            f'''<article class="compare-live-card" data-compare-model="{escape(model_id, quote=True)}"
              data-context="{int(model["context_window"])}" data-max-output="{escape(str(model.get("max_output")), quote=True)}"
              data-pricing-status="{escape(model_pricing_status(model), quote=True)}">
              <div class="compare-live-meta"><span>{escape(model["provider"])}</span><small>Verified {escape(model["provenance"]["verified_at"])}</small></div>
              <h3>{escape(model["model"])}</h3>
              <dl>
                <div><dt>Context</dt><dd>{int(model["context_window"]):,}</dd></div>
                <div><dt>Max output</dt><dd>{escape(model_output_label(model))}</dd></div>
                <div><dt>Input / MTok</dt><dd>{escape(input_price)}</dd></div>
                <div><dt>Cached / MTok</dt><dd>{escape(cached_price)}</dd></div>
                <div><dt>Output / MTok</dt><dd>{escape(output_price)}</dd></div>
                <div><dt>Input types</dt><dd>{escape(modalities)}</dd></div>
              </dl>
              <div class="compare-live-sources"><a href="{escape(evidence["model_identity"], quote=True)}" target="_blank" rel="noopener noreferrer">Specs ↗</a><a href="{escape(evidence["pricing"], quote=True)}" target="_blank" rel="noopener noreferrer">Pricing status ↗</a></div>
            </article>'''
        )
    latest = []
    history = load_model_history()
    for model_id in model_ids:
        model_events = [event for event in history["events"] if event.get("model_id") == model_id]
        if model_events:
            latest.append(model_events[-1])
    latest_verified = max((event["verified_at"] for event in latest), default=verified)
    return f'''<section class="compare-live-facts shell" data-compare-contract data-model-ids="{escape(",".join(model_ids), quote=True)}">
      <div class="intel-section-head"><div><p class="eyebrow">LIVE VERIFIED FACTS</p><h2>Current facts from the SXF model database.</h2></div><span>Catalog {escape(verified)} · History {escape(latest_verified)}</span></div>
      <div class="compare-live-grid">{"".join(cards)}</div>
      <div class="compare-live-foot"><span>Facts are generated from the canonical model catalog, not copied into this comparison.</span><a href="/data/model-pricing.json">Current data ↗</a><a href="/data/model-history.json">Change ledger ↗</a></div>
    </section>'''


def compare_pair_fact_line(model_ids):
    parts = []
    for model_id in model_ids:
        model = model_catalog_entry(model_id)
        context_m = model["context_window"] / 1_000_000
        context_label = f"{context_m:.2f}".rstrip("0").rstrip(".") + "M"
        price_text = comparison_price_text(model_id)
        parts.append(f'{model["model"]}: {price_text} · {context_label}')
    return " | ".join(parts)


def compare_workload_cost(model_id, input_tokens=100000, output_tokens=10000, cached_tokens=0):
    model = model_catalog_entry(model_id)
    if not model_has_official_paid_pricing(model):
        return None
    return estimate_standard_cost(
        model_id,
        uncached_input_tokens=input_tokens,
        output_tokens=output_tokens,
        cached_input_tokens=cached_tokens,
        on_date=MODEL_PRICING_CATALOG["source_verified"],
    )[0]


def compare_decision_items(model_ids):
    models = [model_catalog_entry(model_id) for model_id in model_ids]
    if len(models) != 2:
        return []
    left, right = models
    items = []

    if left["context_window"] != right["context_window"]:
        winner = left if left["context_window"] > right["context_window"] else right
        loser = right if winner is left else left
        ratio = winner["context_window"] / loser["context_window"]
        items.append((
            "Context capacity",
            f'{winner["model"]} publishes the larger context window: {winner["context_window"]:,} vs {loser["context_window"]:,} tokens ({ratio:.1f}×).'
        ))
    else:
        items.append(("Context capacity", f'Both publish a {left["context_window"]:,}-token context window.'))

    left_inputs = set(left.get("modalities", {}).get("input", []))
    right_inputs = set(right.get("modalities", {}).get("input", []))
    if left_inputs != right_inputs:
        left_only = sorted(left_inputs - right_inputs)
        right_only = sorted(right_inputs - left_inputs)
        chunks = []
        if left_only:
            chunks.append(f'{left["model"]} additionally lists {", ".join(left_only)}')
        if right_only:
            chunks.append(f'{right["model"]} additionally lists {", ".join(right_only)}')
        items.append(("Input modalities", "; ".join(chunks) + "."))
    else:
        items.append(("Input modalities", f'Both list {", ".join(sorted(left_inputs)) or "no published input modalities"} as input types.'))

    left_cost = compare_workload_cost(left["model_id"])
    right_cost = compare_workload_cost(right["model_id"])
    if left_cost is not None and right_cost is not None:
        if abs(left_cost - right_cost) < 1e-12:
            text = f'For 100K uncached input + 10K output tokens, both calculate to {catalog_money(left_cost)} at the catalog verification date.'
        else:
            cheaper = left if left_cost < right_cost else right
            cheaper_cost = min(left_cost, right_cost)
            expensive_cost = max(left_cost, right_cost)
            ratio = expensive_cost / cheaper_cost if cheaper_cost else 0
            text = f'For 100K uncached input + 10K output tokens, {cheaper["model"]} is lower at {catalog_money(cheaper_cost)} vs {catalog_money(expensive_cost)} ({ratio:.1f}× difference).'
        items.append(("Direct token cost", text))
    else:
        unavailable = [model["model"] for model in models if not model_has_official_paid_pricing(model)]
        items.append(("Direct token cost", f'Direct Standard token-cost comparison is unavailable because {", ".join(unavailable)} does not have a calculator-eligible provider-published paid rate in the SXF catalog.'))

    left_output = left.get("max_output")
    right_output = right.get("max_output")
    if left_output != right_output:
        items.append(("Output policy", f'{left["model"]}: {model_output_label(left)}. {right["model"]}: {model_output_label(right)}.'))
    return items


def ensure_catalog_model_histories():
    grouped = {}
    for model_id, model in MODEL_PRICING_BY_ID.items():
        path = model.get("sxf_url", "")
        if not path.startswith("/models/") or path == "/models/pricing/":
            continue
        grouped.setdefault(path, []).append(model_id)

    for url, model_ids in grouped.items():
        target = ROOT / url.strip("/") / "index.html"
        if not target.exists():
            continue
        html = target.read_text(encoding="utf-8")
        if "data-model-history" in html and "data-what-changed" in html:
            continue
        title = " / ".join(MODEL_PRICING_BY_ID[mid]["model"] for mid in model_ids)
        fragment = ""
        if "data-what-changed" not in html:
            fragment += model_change_watch_html(model_ids, f"{title}: what changed.")
        if "data-model-history" not in html:
            fragment += model_history_html(model_ids, f"{title} verified history.")
        html = inject_before_main_end(html, fragment)
        target.write_text(html, encoding="utf-8")


def inject_before_main_end(html, fragment):
    if not fragment:
        return html
    marker = "</main>"
    if marker not in html:
        raise RuntimeError("Could not inject model intelligence block: </main> missing")
    return html.replace(marker, fragment + marker, 1)


def inject_compare_contract(html, model_ids):
    fragment = compare_live_facts_html(model_ids) + comparison_evidence_html(model_ids) + compare_change_watch_html(model_ids)
    hero_end = "</section>"
    hero_start = html.find('<section class="comparison-hero')
    if hero_start < 0:
        raise RuntimeError("Comparison page is missing comparison-hero")
    end = html.find(hero_end, hero_start)
    if end < 0:
        raise RuntimeError("Comparison hero section is not closed")
    end += len(hero_end)
    return html[:end] + fragment + html[end:]


def model_catalog_entry(model_id):
    try:
        return MODEL_PRICING_BY_ID[model_id]
    except KeyError as exc:
        raise KeyError(f"Model is missing from canonical pricing catalog: {model_id}") from exc


def model_pricing_status(model):
    return model.get("pricing_status", "not-published")


def model_has_official_paid_pricing(model):
    return (
        model_pricing_status(model) == "official-paid"
        and model.get("calculator_eligible") is True
        and model.get("pricing_basis", {}).get("meter") == "tokens"
        and bool(model.get("pricing", {}).get("standard"))
    )


def active_standard_price(model_id, on_date=None):
    model = model_catalog_entry(model_id)
    if not model_has_official_paid_pricing(model):
        raise RuntimeError(
            f"{model_id} is not calculator-eligible: pricing_status={model_pricing_status(model)!r}"
        )
    schedule = model.get("pricing", {}).get("standard", [])
    target = on_date or datetime.now(timezone.utc).date()
    if isinstance(target, str):
        target = datetime.fromisoformat(target).date()

    for period in schedule:
        start = datetime.fromisoformat(period["start"]).date()
        end = datetime.fromisoformat(period["end"]).date() if period.get("end") else None
        if target >= start and (end is None or target <= end):
            return period
    raise RuntimeError(f"No Standard pricing period for {model_id} on {target.isoformat()}")


def effective_standard_price(model_id, input_tokens=0, on_date=None):
    model = model_catalog_entry(model_id)
    rates = dict(active_standard_price(model_id, on_date))
    long_context = model.get("pricing", {}).get("long_context")
    if long_context and input_tokens > int(long_context["threshold_input_tokens"]):
        multipliers = long_context["multipliers"]
        for key in ("input", "cached_input", "cache_write", "output"):
            if key in rates and key in multipliers:
                rates[key] = rates[key] * multipliers[key]
        rates["long_context_applied"] = True
    else:
        rates["long_context_applied"] = False
    return rates


def catalog_price_label(value):
    value = float(value)
    if value >= 1:
        return f"${value:,.2f}"
    rendered = f"{value:.4f}".rstrip("0").rstrip(".")
    if "." not in rendered:
        rendered += ".00"
    else:
        whole, fraction = rendered.split(".", 1)
        rendered = whole + "." + fraction.ljust(2, "0")
    return "$" + rendered


def catalog_reference_variant(variant):
    model = model_catalog_entry(variant["model_id"])
    price = active_standard_price(variant["model_id"])
    cutoff = model.get("knowledge_cutoff")
    if cutoff and len(cutoff) == 10:
        cutoff = datetime.fromisoformat(cutoff).strftime("%b %-d, %Y")
    elif cutoff and len(cutoff) == 7:
        cutoff = datetime.fromisoformat(cutoff + "-01").strftime("%b %Y")
    else:
        cutoff = cutoff or "Not listed"

    return {
        **variant,
        "context": f'{int(model["context_window"]):,}',
        "max_output": model_output_label(model),
        "knowledge_cutoff": cutoff,
        "input_price": catalog_price_label(price["input"]),
        "cached_price": catalog_price_label(price["cached_input"]) if price.get("cached_input") is not None else "—",
        "output_price": catalog_price_label(price["output"]),
        "source": model["official_sources"][0],
    }


def estimate_standard_cost(model_id, uncached_input_tokens=0, output_tokens=0, cached_input_tokens=0, on_date=None, pricing_input_tokens=None):
    uncached_input_tokens = int(uncached_input_tokens)
    cached_input_tokens = int(cached_input_tokens)
    output_tokens = int(output_tokens)
    if min(uncached_input_tokens, cached_input_tokens, output_tokens) < 0:
        raise ValueError("Token counts must be non-negative")

    total_input_tokens = uncached_input_tokens + cached_input_tokens
    tier_input_tokens = total_input_tokens if pricing_input_tokens is None else int(pricing_input_tokens)
    if tier_input_tokens < 0:
        raise ValueError("pricing_input_tokens must be non-negative")
    model = model_catalog_entry(model_id)
    quantity = float(model.get("pricing_basis", {}).get("quantity", 1_000_000))
    if model.get("pricing_basis", {}).get("meter") != "tokens" or quantity <= 0:
        raise RuntimeError(f"{model_id} does not use calculator-compatible token pricing")
    rates = effective_standard_price(model_id, tier_input_tokens, on_date)
    cost = (
        uncached_input_tokens / quantity * rates["input"]
        + cached_input_tokens / quantity * rates.get("cached_input", rates["input"])
        + output_tokens / quantity * rates["output"]
    )
    return cost, rates


def catalog_money(value, precision=4):
    rendered = f"{float(value):,.{precision}f}".rstrip("0").rstrip(".")
    return "$" + (rendered or "0")


def catalog_display_model(model_id, **overrides):
    model = model_catalog_entry(model_id)
    price = active_standard_price(model_id)
    cutoff = model.get("knowledge_cutoff")
    if cutoff and len(cutoff) == 10:
        cutoff = datetime.fromisoformat(cutoff).strftime("%b %-d, %Y")
    elif cutoff and len(cutoff) == 7:
        cutoff = datetime.fromisoformat(cutoff + "-01").strftime("%b %Y")
    else:
        cutoff = cutoff or "Not listed"

    cache_write = None
    if "cache_write" in price:
        cache_write = catalog_price_label(price["cache_write"])
    elif "cache_write_5m" in price:
        one_hour = price.get("cache_write_1h")
        cache_write = catalog_price_label(price["cache_write_5m"])
        if one_hour is not None:
            cache_write += " / " + catalog_price_label(one_hour)

    row = {
        "name": model["model"],
        "provider": model["provider"],
        "model_id": model["model_id"],
        "positioning": model["positioning"],
        "context": f'{int(model["context_window"]):,}',
        "max_output": model_output_label(model),
        "knowledge_cutoff": cutoff,
        "input_price": catalog_price_label(price["input"]),
        "cached_price": catalog_price_label(price["cached_input"]) if price.get("cached_input") is not None else "—",
        "cache_write": cache_write or "—",
        "output_price": catalog_price_label(price["output"]),
        "source": model["official_sources"][0],
        "sxf_url": model["sxf_url"],
    }
    row.update(overrides)
    return row

def parse_date(value):
    if not value:
        return None
    try:
        d = email.utils.parsedate_to_datetime(value)
        if d.tzinfo is None:
            d = d.replace(tzinfo=timezone.utc)
        return d.astimezone(timezone.utc)
    except Exception:
        pass
    try:
        d = datetime.fromisoformat(value.replace("Z", "+00:00"))
        if d.tzinfo is None:
            d = d.replace(tzinfo=timezone.utc)
        return d.astimezone(timezone.utc)
    except Exception:
        return None

def categorize(title, source):
    t = title.replace("‑", "-").replace("–", "-").replace("—", "-").lower()

    # Product and developer surfaces beat incidental model mentions.
    if re.search(r"\bcopilot\b|\bchatgpt\b|\bagents? api\b|\bsandbox(?:ing)?\b|\bcode reviews?\b|\bgithub actions\b", t):
        if re.search(r"\bresearch\b|\bbenchmark\b|\bevaluation\b|\bstudy\b|\bsafety\b|\bmisalignment\b", t):
            return "Research"
        return "Tools"

    if re.search(r"\bresearch\b|\bpaper\b|\bstudy\b|\bbenchmark\b|\bevaluation\b|\bscience\b|\bsafety\b|\bmisalignment\b|\bassessment\b", t):
        return "Research"

    if re.search(r"\bopen[- ]source\b|\bopen weights?\b|\bweights\b|\bcheckpoint\b|\bllama\.cpp\b|\bmlx\b|\bquants?\b|\brepository release\b", t):
        return "Open Source"

    if re.search(r"\bgpt[- ]\d+(?:\.\d+)?\b|\bclaude(?:\s+[a-z]+)?\s+\d+(?:\.\d+)?\b|\bgemini(?:\s+\d+(?:\.\d+)?)?\b|\blfm\d+(?:\.\d+)?\b|\bllm\b|\bfoundation models?\b|\bvision-language model\b|\bmultimodal model\b|\breasoning model\b|\bembedding model\b", t):
        return "Models"

    source_config = SOURCE_BY_NAME.get(source, {})
    return source_config.get("default_category", "Tools")

def classify_tags(title, source, category):
    t = title.replace("‑", "-").replace("–", "-").replace("—", "-").lower()
    tags = []
    rules = [
        ("GitHub Copilot", r"\bcopilot\b"),
        ("Coding AI", r"\bcode\b|\bcoding\b|\bcodex\b|\bdeveloper\b|\brepository\b|\bjetbrains\b"),
        ("AI Agents", r"\bagents?\b|\bagentic\b"),
        ("Security", r"\bsecurity\b|\bsafety\b|\bsandbox(?:ing)?\b|\bcyber\b|\bproof of presence\b"),
        ("Multimodal AI", r"\bmultimodal\b|\bvision\b|\bimage\b|\bvideo\b|\bvoice\b|\baudio\b"),
        ("Open Source AI", r"\bopen[- ]source\b|\bopen weights?\b|\bweights\b|\bcheckpoint\b|\bllama\.cpp\b|\bmlx\b|\bquants?\b"),
        ("Research", r"\bresearch\b|\bpaper\b|\bstudy\b|\bbenchmark\b|\bevaluation\b|\bscience\b"),
    ]
    for label, pattern in rules:
        if re.search(pattern, t):
            tags.append(label)
    if source == "OpenAI":
        tags.append("OpenAI")
    elif source == "Google AI":
        tags.append("Google AI")
    if category == "Open Source" and "Open Source AI" not in tags:
        tags.append("Open Source AI")
    return list(dict.fromkeys(tags))

def fetch(url, attempts=3):
    last_error = None
    for attempt in range(attempts):
        req = urllib.request.Request(
            url,
            headers={
                "User-Agent": USER_AGENT,
                "Accept": "application/rss+xml, application/atom+xml, application/xml, text/xml, */*",
            },
        )
        try:
            with urllib.request.urlopen(req, timeout=25) as r:
                return r.read()
        except Exception as exc:
            last_error = exc
            if attempt + 1 < attempts:
                time.sleep(1.0 * (2 ** attempt))
    raise last_error

def source_accepts_item(source_config, title, summary):
    filter_name = source_config.get("filter")
    if not filter_name:
        return True
    if filter_name == "google-research-ai":
        return bool(GOOGLE_RESEARCH_AI_PATTERN.search(f"{title} {summary}"))
    if filter_name == "microsoft-ai":
        return bool(MICROSOFT_AI_PATTERN.search(f"{title} {summary}"))
    raise RuntimeError(f"Unknown source filter: {filter_name}")


def parse_feed_with_metrics(source, body):
    root = ET.fromstring(body)
    rows = []
    for item in root.findall(".//item"):
        title = clean_title(text(item, "title"))
        link = text(item, "link")
        published = parse_date(text(item, "pubDate", "date"))
        summary = clean_summary(text(item, "description", "summary", "content"))
        if title and link and published is not None:
            rows.append((title, link, published, summary))
    if not rows:
        for entry in root.findall(".//{*}entry"):
            title = clean_title(text(entry, "{*}title"))
            link = ""
            for ln in entry.findall("{*}link"):
                href = ln.attrib.get("href", "")
                rel = ln.attrib.get("rel", "alternate")
                if href and rel in ("alternate", ""):
                    link = href
                    break
            published = parse_date(text(entry, "{*}published", "{*}updated"))
            summary = clean_summary(text(entry, "{*}summary", "{*}content"))
            if title and link and published is not None:
                rows.append((title, link, published, summary))

    output = []
    source_config = SOURCE_BY_NAME.get(source, {"name": source})
    relevance_rejected = 0
    for title, link, published, summary in rows:
        if not source_accepts_item(source_config, title, summary):
            relevance_rejected += 1
            continue
        category = categorize(title, source)
        output.append({
            "title": title,
            "url": link,
            "source": source,
            "published": published.isoformat().replace("+00:00", "Z"),
            "category": category,
            "tags": classify_tags(title, source, category),
            "summary": summary,
        })
    return output, {
        "parsed_candidate_count": len(rows),
        "relevance_accepted_count": len(output),
        "relevance_rejection_count": relevance_rejected,
    }

def parse_feed(source, body):
    items, _metrics = parse_feed_with_metrics(source, body)
    return items

def fetch_meta_description(url):
    try:
        req = urllib.request.Request(url, headers={"User-Agent": USER_AGENT, "Accept": "text/html,*/*"})
        with urllib.request.urlopen(req, timeout=12) as r:
            ctype = (r.headers.get("Content-Type") or "").lower()
            if "html" not in ctype:
                return ""
            raw = r.read(350000).decode("utf-8", "ignore")
        patterns = [
            r'<meta[^>]+(?:name|property)=["\'](?:description|og:description)["\'][^>]+content=["\']([^"\']+)["\']',
            r'<meta[^>]+content=["\']([^"\']+)["\'][^>]+(?:name|property)=["\'](?:description|og:description)["\']',
        ]
        for pattern in patterns:
            m = re.search(pattern, raw, re.I | re.S)
            if m:
                value = clean_summary(m.group(1))
                if 40 <= len(value) <= 900:
                    return value
    except Exception:
        pass
    return ""

def enrich_summaries(items, existing_by_url):
    enriched = 0
    floor = datetime.min.replace(tzinfo=timezone.utc)
    for item in sorted(items, key=lambda x: parse_date(x["published"]) or floor, reverse=True):
        if enriched >= MAX_META_ENRICH_PER_RUN:
            break
        previous = existing_by_url.get(item["url"], {})
        if item.get("summary") or previous.get("summary"):
            continue
        summary = fetch_meta_description(item["url"])
        if summary:
            item["summary"] = summary
            item["summary_origin"] = "source-meta"
            enriched += 1
    return enriched

def valid_url(url):
    p = urlparse(url)
    return p.scheme in ("http", "https") and bool(p.netloc)

def relative_time(date_str):
    d = parse_date(date_str)
    if d is None:
        return ""
    diff = max(timedelta(0), datetime.now(timezone.utc) - d)
    minutes = int(diff.total_seconds() // 60)
    if minutes < 2:
        return "just now"
    if minutes < 60:
        return f"{minutes}m ago"
    hours = minutes // 60
    if hours < 24:
        return f"{hours}h ago"
    days = hours // 24
    if days < 7:
        return f"{days}d ago"
    return d.strftime("%b %-d")

def featured_html(item):
    href = item.get("signal_url", item["url"])
    return f'''<a class="featured-story" href="{escape(href, quote=True)}">
  <div class="featured-main">
    <div>
      <div class="featured-topline"><strong>{escape(item["source"])}</strong><i></i><span>{escape(relative_time(item["published"]))}</span></div>
      <h3 class="featured-title">{escape(item["title"])}</h3>
    </div>
    <div class="featured-footer"><span class="category-pill">{escape(item["category"])}</span><span class="open-label">Read signal <b>↗</b></span></div>
  </div>
  <div class="featured-visual" aria-hidden="true"><span class="signal-cross">+</span><span class="signal-number">01</span></div>
</a>'''

def cards_html(items):
    rows = []
    for item in items:
        href = item.get("signal_url", item["url"])
        rows.append(f'''<a class="story-card" href="{escape(href, quote=True)}">
  <div class="story-card-top"><span class="story-source">{escape(item["source"])}</span><span class="story-time">{escape(relative_time(item["published"]))}</span></div>
  <h3 class="story-title">{escape(item["title"])}</h3>
  <div class="story-card-bottom"><span class="category-pill">{escape(item["category"])}</span><span class="story-arrow" aria-hidden="true">↗</span></div>
</a>''')
    return "\n".join(rows)

def replace_block(source, start, end, body):
    pattern = re.compile(re.escape(start) + r".*?" + re.escape(end), re.S)
    replacement = f"{start}\n{body}\n{end}"
    return pattern.sub(lambda _m: replacement, source, count=1)

HOMEPAGE_SIGNAL_LIMIT = 8
HOMEPAGE_SOURCE_LIMIT = 2

HOMEPAGE_AGENT_PATTERN = re.compile(
    r"\\bagents?\\b|\\bagentic\\b|multi-agent|computer use|tool use|"
    r"agent memory|agent reliability|agent security|autonomous agent",
    re.I,
)
HOMEPAGE_MODEL_PATTERN = re.compile(
    r"\\bmodels?\\b|gpt[- .]?\\d|claude|gemini|grok|llama|"
    r"reasoning model|context window|token pricing|multimodal model",
    re.I,
)
HOMEPAGE_RESEARCH_PATTERN = re.compile(
    r"\\bresearch\\b|benchmark|evaluation|evals?|safety|alignment|"
    r"paper|study|science|methodology|reproducib",
    re.I,
)
HOMEPAGE_HIGH_IMPACT_PATTERN = re.compile(
    r"introduc|launch|release|generally available|new generation|"
    r"pricing|price|context window|capabilit|reasoning|multimodal|"
    r"benchmark|evaluation|safety|security|memory|reliability|"
    r"open[- ]sourc|frontier",
    re.I,
)
HOMEPAGE_LOW_IMPACT_PATTERN = re.compile(
    r"retention|saved views?|new fields?|runner image|node \\d+|"
    r"permissions?|comments? api|dashboard|default enablement|"
    r"minor|maintenance|deprecat(?:e|ed|ion)",
    re.I,
)

def homepage_signal_text(item):
    return " ".join(
        str(item.get(key, "") or "")
        for key in ("title", "summary", "category", "source")
    )

def homepage_signal_bucket(item):
    text = homepage_signal_text(item)
    if HOMEPAGE_AGENT_PATTERN.search(text):
        return "Agents"
    if item.get("category") == "Models" or HOMEPAGE_MODEL_PATTERN.search(text):
        return "Models"
    if item.get("category") == "Research" or HOMEPAGE_RESEARCH_PATTERN.search(text):
        return "Research"
    return "Other"

def homepage_signal_score(item, now=None):
    now = now or datetime.now(timezone.utc)
    text = homepage_signal_text(item)
    bucket = homepage_signal_bucket(item)
    score = {"Models": 34, "Agents": 36, "Research": 32, "Other": 8}[bucket]

    published = parse_date(item.get("published", ""))
    if published:
        age_hours = max(0.0, (now - published).total_seconds() / 3600)
        if age_hours <= 12:
            score += 18
        elif age_hours <= 24:
            score += 15
        elif age_hours <= 72:
            score += 10
        elif age_hours <= 168:
            score += 5
        elif age_hours > 336:
            score -= 8

    if HOMEPAGE_HIGH_IMPACT_PATTERN.search(text):
        score += 16
    if HOMEPAGE_LOW_IMPACT_PATTERN.search(text):
        score -= 18

    source = (item.get("source") or "").strip()
    if source in {"OpenAI", "Anthropic", "Google AI", "Google Research", "Meta", "xAI", "Hugging Face"}:
        score += 6
    elif source == "GitHub":
        score += 2

    if item.get("signal_url"):
        score += 2
    if item.get("summary"):
        score += 2
    return score

def select_homepage_signals(items, limit=HOMEPAGE_SIGNAL_LIMIT):
    if not items:
        return []

    now = datetime.now(timezone.utc)
    ranked = sorted(
        items,
        key=lambda item: (
            homepage_signal_score(item, now),
            parse_date(item.get("published", "")) or datetime.min.replace(tzinfo=timezone.utc),
        ),
        reverse=True,
    )

    # Target mix: 3 Models, 2 Agents, 2 Research, 1 flexible.
    targets = {"Models": 3, "Agents": 2, "Research": 2}
    selected = []
    selected_urls = set()
    source_counts = {}

    def can_add(item):
        url = item.get("signal_url", item.get("url", ""))
        source = item.get("source", "")
        return (
            bool(url)
            and url not in selected_urls
            and source_counts.get(source, 0) < HOMEPAGE_SOURCE_LIMIT
        )

    def add(item):
        url = item.get("signal_url", item.get("url", ""))
        source = item.get("source", "")
        selected.append(item)
        selected_urls.add(url)
        source_counts[source] = source_counts.get(source, 0) + 1

    for bucket, target in targets.items():
        for item in ranked:
            if len([x for x in selected if homepage_signal_bucket(x) == bucket]) >= target:
                break
            if homepage_signal_bucket(item) == bucket and can_add(item):
                add(item)

    # Fill remaining slots by score while preserving source diversity.
    for item in ranked:
        if len(selected) >= limit:
            break
        if can_add(item):
            add(item)

    # If strict source diversity leaves gaps, relax it only as a last resort.
    if len(selected) < limit:
        for item in ranked:
            if len(selected) >= limit:
                break
            url = item.get("signal_url", item.get("url", ""))
            if url and url not in selected_urls:
                add(item)

    selected.sort(
        key=lambda item: (
            homepage_signal_score(item, now),
            parse_date(item.get("published", "")) or datetime.min.replace(tzinfo=timezone.utc),
        ),
        reverse=True,
    )
    return selected[:limit]


def homepage_change_cards(limit=3):
    history = load_model_history()
    candidates = [event for event in history["events"] if event.get("type") != "baseline"]
    candidates.sort(key=lambda event: (event.get("verified_at", ""), event.get("sequence", 0)), reverse=True)

    selected = []
    providers = set()
    for event in candidates:
        model = MODEL_PRICING_BY_ID.get(event.get("model_id"), {})
        provider = model.get("provider") or event.get("snapshot", {}).get("provider") or "Primary source"
        if provider in providers:
            continue
        selected.append(event)
        providers.add(provider)
        if len(selected) >= limit:
            break

    if len(selected) < limit:
        used = {event.get("event_id") for event in selected}
        for event in candidates:
            if event.get("event_id") in used:
                continue
            selected.append(event)
            if len(selected) >= limit:
                break

    cards = []
    for event in selected:
        model_id = event.get("model_id", "")
        snapshot = event.get("snapshot", {})
        model = MODEL_PRICING_BY_ID.get(model_id, {})
        name = model.get("model") or snapshot.get("model") or model_id
        provider = model.get("provider") or snapshot.get("provider") or "Primary source"
        href = model.get("sxf_url") or f"/models/{slugify(name)}/"
        context = snapshot.get("context_window", model.get("context_window"))
        context_text = compact_token_count(context) if context is not None else "Not published"
        pricing = snapshot.get("pricing", {}).get("standard") or model.get("pricing", {}).get("standard") or []
        active = pricing[-1] if pricing else {}
        input_price = active.get("input")
        output_price = active.get("output")
        price_text = "Pricing not published"
        if input_price is not None and output_price is not None:
            price_text = f'{catalog_price_label(input_price)} in · {catalog_price_label(output_price)} out / MTok'
        evidence = event.get("evidence", {})
        source = evidence.get("model") or evidence.get("provider") or evidence.get("pricing") or (model.get("official_sources") or [""])[0]
        verified = event.get("verified_at", "")
        event_type = event.get("type", "change")
        if event_type == "model_added":
            label = "NEW MODEL"
            change_text = "Added to the verified SXF model index"
        else:
            label = "VERIFIED CHANGE"
            change_text = "Verified model facts changed"

        cards.append(f'''<article class="change-card">
          <div class="change-card-top"><span>{escape(label)}</span><small>{escape(provider)}</small></div>
          <h3><a href="{escape(href, quote=True)}">{escape(name)}</a></h3>
          <p class="change-summary">{escape(change_text)}</p>
          <dl class="change-facts">
            <div><dt>Context</dt><dd>{escape(context_text)}</dd></div>
            <div><dt>API pricing</dt><dd>{escape(price_text)}</dd></div>
          </dl>
          <div class="change-card-foot"><span>Verified {escape(verified)}</span>{f'<a href="{escape(source, quote=True)}" target="_blank" rel="noopener noreferrer">Source ↗</a>' if source else ''}</div>
        </article>''')

    return "\n".join(cards)

def update_index(items):
    if not INDEX.exists() or not items:
        return

    homepage_items = select_homepage_signals(items)
    if not homepage_items:
        return

    page = INDEX.read_text(encoding="utf-8")
    page = replace_block(page, "<!-- SXF:WHAT_CHANGED_START -->", "<!-- SXF:WHAT_CHANGED_END -->", homepage_change_cards())
    page = replace_block(page, "<!-- SXF:FEATURED_START -->", "<!-- SXF:FEATURED_END -->", featured_html(homepage_items[0]))
    page = replace_block(page, "<!-- SXF:FEED_START -->", "<!-- SXF:FEED_END -->", cards_html(homepage_items[1:]))
    item_list = {
        "@context": "https://schema.org",
        "@type": "ItemList",
        "@id": "https://sxf.si/#latest-signals",
        "name": "Featured AI model, agent and research signals",
        "description": "A curated list of current AI model, agent and research signals tracked by SXF / AI.",
        "itemListOrder": "https://schema.org/ItemListOrderDescending",
        "mainEntityOfPage": {"@id": "https://sxf.si/#webpage"},
        "numberOfItems": len(homepage_items),
        "itemListElement": [
            {
                "@type": "ListItem",
                "position": i + 1,
                "item": {"@type": "Thing", "name": item["title"], "url": item.get("signal_url", item["url"])},
            }
            for i, item in enumerate(homepage_items)
        ],
    }
    schema = '<script type="application/ld+json" id="latest-signals-schema">' + json.dumps(item_list, ensure_ascii=False, separators=(",", ":")).replace("<", "\\u003c") + "</script>"
    page = replace_block(page, "<!-- SXF:ITEMLIST_START -->", "<!-- SXF:ITEMLIST_END -->", schema)
    INDEX.write_text(page, encoding="utf-8")


