def select_current_items(archive, cutoff):
    selected = []
    expansion_counts = {name: 0 for name in SOURCE_EXPANSION_NAMES}
    expansion_total = 0

    for item in archive:
        published = parse_date(item.get("published", ""))
        if published is None or published < cutoff:
            continue

        source = item.get("source", "")
        source_config = SOURCE_BY_NAME.get(source, {})
        status = source_config.get("status", "live")
        if status in {"shadow", "disabled"}:
            continue

        max_current = source_config.get("max_current", MAX_ITEMS)
        source_selected = sum(1 for selected_item in selected if selected_item.get("source") == source)
        if source_selected >= max_current:
            continue

        if source in SOURCE_EXPANSION_NAMES:
            if expansion_counts[source] >= SOURCE_EXPANSION_MAX_CURRENT_PER_SOURCE:
                continue
            if expansion_total >= SOURCE_EXPANSION_MAX_CURRENT_TOTAL:
                continue
            expansion_counts[source] += 1
            expansion_total += 1

        selected.append(item)
        if len(selected) >= MAX_ITEMS:
            break

    return selected


def main():
    from model_history import sync_model_history_file
    history_result = sync_model_history_file(MODEL_PRICING_PATH, MODEL_HISTORY_PATH)

    incoming = []
    errors = []
    source_metrics = {}
    shadow_candidates = []
    shadow_rejections = []
    now = datetime.now(timezone.utc)

    for source_config in SOURCE_CONFIGS:
        source = source_config["name"]
        status = source_config["status"]
        metrics = {
            "status": status,
            "fetch_success": False,
            "fetch_failure": False,
            "parsed_candidate_count": 0,
            "relevance_accepted_count": 0,
            "quality_accepted_count": 0,
            "accepted_candidate_count": 0,
            "rejected_candidate_count": 0,
            "duplicate_count": 0,
            "age_rejection_count": 0,
            "relevance_rejection_count": 0,
            "quality_rejection_count": 0,
            "publish_count": 0,
            "adapter": source_config.get("adapter"),
            "adapter_contract_version": ADAPTER_CONTRACT_VERSION if source_config.get("adapter") != "rss" else None,
            "adapter_discovered_count": 0,
            "adapter_invalid_count": 0,
            "adapter_fetch_failure_count": 0,
            "schema_drift": False,
            "last_successful_fetch": None,
            "errors": [],
        }
        source_metrics[source] = metrics

        if status == "disabled":
            continue
        adapter = source_config.get("adapter")
        if adapter == "pending":
            metrics["errors"].append("No verified automated feed adapter configured")
            continue

        try:
            if adapter == "rss":
                parsed, parse_metrics = parse_feed_with_metrics(source, fetch(source_config["url"]))
            else:
                raw_items, adapter_diagnostics = run_source_adapter(
                    source_config,
                    user_agent=USER_AGENT,
                    now=now,
                )
                metrics["adapter_discovered_count"] = adapter_diagnostics.get("discovered_count", 0)
                metrics["adapter_invalid_count"] = adapter_diagnostics.get("invalid_count", 0)
                metrics["adapter_fetch_failure_count"] = adapter_diagnostics.get("fetch_failure_count", 0)
                metrics["schema_drift"] = bool(adapter_diagnostics.get("schema_drift"))
                metrics["errors"].extend(adapter_diagnostics.get("errors", []))

                parsed = []
                relevance_rejected = 0
                for item in raw_items:
                    if not source_accepts_item(source_config, item["title"], item.get("summary", "")):
                        relevance_rejected += 1
                        continue
                    row = dict(item)
                    row["category"] = categorize(row["title"], source)
                    row["tags"] = classify_tags(row["title"], source, row["category"])
                    parsed.append(row)
                parse_metrics = {
                    "parsed_candidate_count": len(raw_items),
                    "relevance_accepted_count": len(parsed),
                    "relevance_rejection_count": relevance_rejected,
                }

            metrics.update(parse_metrics)
            metrics["fetch_success"] = True
            metrics["last_successful_fetch"] = now.isoformat().replace("+00:00", "Z")
            seen_urls = set()
            deduped = []
            for item in parsed:
                if item["url"] in seen_urls:
                    metrics["duplicate_count"] += 1
                    continue
                seen_urls.add(item["url"])
                deduped.append(item)

            candidate_age_days = SHADOW_RETENTION_DAYS if status == "shadow" else INITIAL_ARCHIVE_DAYS
            candidate_cutoff = now - timedelta(days=candidate_age_days)
            fresh_candidates = []
            for item in deduped:
                published = parse_date(item.get("published", ""))
                if published is None or published < candidate_cutoff:
                    metrics["age_rejection_count"] += 1
                    continue
                fresh_candidates.append(item)

            if status == "shadow":
                prepared_shadow = prepare_items(fresh_candidates)
                accepted_shadow = [item for item in prepared_shadow if item.get("seo_eligible")]
                rejected_shadow = [item for item in prepared_shadow if not item.get("seo_eligible")]
                metrics["quality_rejection_count"] = len(rejected_shadow)
                metrics["quality_accepted_count"] = len(accepted_shadow)
                metrics["accepted_candidate_count"] = len(accepted_shadow)
                shadow_candidates.extend(accepted_shadow)
                shadow_rejections.extend(
                    shadow_quality_rejection_record(item, now.isoformat().replace("+00:00", "Z"))
                    for item in rejected_shadow
                )
            else:
                metrics["quality_accepted_count"] = len(fresh_candidates)
                metrics["accepted_candidate_count"] = len(fresh_candidates)
                incoming.extend(fresh_candidates)

            metrics["rejected_candidate_count"] = (
                metrics["relevance_rejection_count"]
                + metrics["duplicate_count"]
                + metrics["age_rejection_count"]
                + metrics["quality_rejection_count"]
            )
        except Exception as exc:
            message = f"{source}: {exc}"
            metrics["fetch_failure"] = True
            if adapter != "rss" and "drift" in exc.__class__.__name__.lower():
                metrics["schema_drift"] = True
            metrics["errors"].append(str(exc))
            errors.append(message)

    existing = load_items(ARCHIVE_OUT)
    if not existing:
        existing = load_items(OUT)
    existing_by_url = {item.get("url"): item for item in existing if item.get("url")}
    ingest_cutoff = datetime.now(timezone.utc) - timedelta(days=INITIAL_ARCHIVE_DAYS)
    incoming = [
        item for item in incoming
        if parse_date(item.get("published", "")) is not None and parse_date(item["published"]) >= ingest_cutoff
    ]
    enriched = enrich_summaries(incoming, existing_by_url)

    archive = merge_archive(existing, incoming)
    if not archive:
        raise RuntimeError("No valid signals available after archive merge")

    cutoff = datetime.now(timezone.utc) - timedelta(days=MAX_AGE_DAYS)
    current = select_current_items(archive, cutoff)
    if not current:
        current = archive[:MAX_ITEMS]

    now_iso = datetime.now(timezone.utc).isoformat().replace("+00:00", "Z")
    archive_source_counts = {
        source_config["name"]: sum(1 for item in archive if item.get("source") == source_config["name"])
        for source_config in SOURCES
    }
    current_source_counts = {
        source_config["name"]: sum(1 for item in current if item.get("source") == source_config["name"])
        for source_config in SOURCES
    }
    for name, count in current_source_counts.items():
        if name in source_metrics:
            source_metrics[name]["publish_count"] = count

    shadow_cutoff = now - timedelta(days=SHADOW_RETENTION_DAYS)
    previous_shadow_payload = {}
    if SOURCE_SHADOW_PATH.exists():
        try:
            previous_shadow_payload = json.loads(SOURCE_SHADOW_PATH.read_text(encoding="utf-8"))
        except Exception:
            previous_shadow_payload = {}
    previous_shadow = previous_shadow_payload.get("items", []) if isinstance(previous_shadow_payload, dict) else []
    previous_rejections = previous_shadow_payload.get("rejected_items", []) if isinstance(previous_shadow_payload, dict) else []
    retained_shadow = [
        item for item in previous_shadow
        if parse_date(item.get("published", "")) is not None
        and parse_date(item["published"]) >= shadow_cutoff
        and SOURCE_BY_NAME.get(item.get("source"), {}).get("status") == "shadow"
    ]
    shadow_by_url = {item["url"]: item for item in retained_shadow if item.get("url")}
    for item in shadow_candidates:
        published = parse_date(item.get("published", ""))
        if published is None or published < shadow_cutoff:
            continue
        shadow_by_url[item["url"]] = item

    bounded_shadow = []
    per_source_shadow_counts = {}
    for item in sorted(shadow_by_url.values(), key=lambda row: parse_date(row["published"]), reverse=True):
        source = item["source"]
        if per_source_shadow_counts.get(source, 0) >= SHADOW_MAX_ITEMS_PER_SOURCE:
            continue
        bounded_shadow.append(item)
        per_source_shadow_counts[source] = per_source_shadow_counts.get(source, 0) + 1

    rejection_by_url = {}
    for item in previous_rejections:
        published = parse_date(item.get("published", ""))
        if published is None or published < shadow_cutoff:
            continue
        if SOURCE_BY_NAME.get(item.get("source"), {}).get("status") != "shadow":
            continue
        rejection_by_url[item.get("url")] = item
    for item in shadow_rejections:
        previous = rejection_by_url.get(item["url"])
        if previous:
            item["first_rejected_at"] = previous.get("first_rejected_at", item["first_rejected_at"])
        rejection_by_url[item["url"]] = item

    accepted_shadow_urls = {item.get("url") for item in bounded_shadow}
    bounded_rejections = []
    per_source_rejection_counts = {}
    for item in sorted(
        rejection_by_url.values(),
        key=lambda row: parse_date(row.get("published", "")) or datetime.min.replace(tzinfo=timezone.utc),
        reverse=True,
    ):
        source = item.get("source")
        if item.get("url") in accepted_shadow_urls:
            continue
        if per_source_rejection_counts.get(source, 0) >= SHADOW_REJECTED_MAX_ITEMS_PER_SOURCE:
            continue
        bounded_rejections.append(item)
        per_source_rejection_counts[source] = per_source_rejection_counts.get(source, 0) + 1

    source_health = {
        "configured": len(SOURCE_CONFIGS),
        "publishing_configured": len(SOURCES),
        "lifecycle_version": SOURCE_LIFECYCLE_VERSION,
        "archive_counts": archive_source_counts,
        "current_counts": current_source_counts,
        "sources": source_metrics,
        "errors": errors,
    }

    ARCHIVE_OUT.parent.mkdir(parents=True, exist_ok=True)
    SOURCE_SHADOW_PATH.write_text(json.dumps({
        "updated_at": now_iso,
        "retention_days": SHADOW_RETENTION_DAYS,
        "max_items_per_source": SHADOW_MAX_ITEMS_PER_SOURCE,
        "max_rejected_items_per_source": SHADOW_REJECTED_MAX_ITEMS_PER_SOURCE,
        "items": bounded_shadow,
        "rejected_items": bounded_rejections,
        "source_health": source_health,
    }, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")
    ARCHIVE_OUT.write_text(json.dumps({
        "updated_at": now_iso,
        "items": archive,
        "feed_errors": errors,
        "scoring_version": "sxf-signal-score-v2",
        "topic_relevance_version": TOPIC_RELEVANCE_VERSION,
        "source_expansion_version": SOURCE_EXPANSION_VERSION,
        "source_lifecycle_version": SOURCE_LIFECYCLE_VERSION,
        "source_health": source_health,
        "seo_quality_version": "sxf-seo-quality-v1",
    }, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

    OUT.write_text(json.dumps({
        "updated_at": now_iso,
        "items": [client_item(item) for item in current],
        "feed_errors": errors,
        "scoring_version": "sxf-signal-score-v2",
        "topic_relevance_version": TOPIC_RELEVANCE_VERSION,
        "source_expansion_version": SOURCE_EXPANSION_VERSION,
        "source_lifecycle_version": SOURCE_LIFECYCLE_VERSION,
        "source_health": source_health,
    }, ensure_ascii=False, indent=2) + "\n", encoding="utf-8")

    update_index(current)
    update_section_pages(current)
    build_discovery_pages(archive, current)
    normalize_static_shells()
    update_sitemap(archive)
    print(
        f"Wrote {len(current)} current signals from {len(archive)} archived signals; "
        f"enriched {enriched} summaries; source errors: {len(errors)}; "
        f"source counts: {current_source_counts}; "
        f"model history: {history_result['events']} events / +{history_result['events_added']} new"
    )
    for error in errors:
        print(f"Source warning: {error}")
if __name__ == "__main__":
    main()
def load_source_registry():
    data = json.loads(SOURCE_CONFIG_PATH.read_text(encoding="utf-8"))
    statuses = set(data.get("statuses", []))
    if statuses != SOURCE_STATUSES:
        raise RuntimeError(f"source-config statuses must be {sorted(SOURCE_STATUSES)}")
    sources = data.get("sources")
    if not isinstance(sources, list) or not sources:
        raise RuntimeError("source-config.json must contain a non-empty sources array")

    names = []
    for source in sources:
        name = source.get("name")
        status = source.get("status")
        max_current = source.get("max_current")
        if not name or not isinstance(name, str):
            raise RuntimeError("Every source must have a name")
        if status not in SOURCE_STATUSES:
            raise RuntimeError(f"{name}: invalid source status {status!r}")
        if not isinstance(max_current, int) or max_current < 0:
            raise RuntimeError(f"{name}: max_current must be a non-negative integer")
        if status == "shadow" and max_current != 0:
            raise RuntimeError(f"{name}: shadow sources must have max_current=0")
        if status == "disabled" and max_current != 0:
            raise RuntimeError(f"{name}: disabled sources must have max_current=0")
        adapter = source.get("adapter")
        if adapter not in {"rss", "pending", "anthropic-sitemap", "meta-blog", "xai-news"}:
            raise RuntimeError(f"{name}: unsupported adapter {adapter!r}")
        if adapter in {"rss", "anthropic-sitemap", "meta-blog", "xai-news"} and not source.get("url"):
            raise RuntimeError(f"{name}: {adapter} adapter requires a URL")
        names.append(name)
    if len(names) != len(set(names)):
        raise RuntimeError("source-config.json contains duplicate source names")
    return data, sources

SOURCE_REGISTRY, SOURCE_CONFIGS = load_source_registry()
