def model_reference(name):
    if name == "Claude Opus 5.5":
        return MODEL_REFERENCE["Claude Opus 5.5"]
    if name == "GPT-5.6":
        return MODEL_REFERENCE["GPT-5.6"]
    if name == "GPT-6" or name.startswith("GPT-6 "):
        return MODEL_REFERENCE["GPT-6"]
    return None


