def model_comparison_links_html(model_id, limit=4):
    matches = [
        comparison for comparison in MODEL_COMPARISON_CATALOG["comparisons"]
        if comparison.get("indexable") is True and model_id in comparison.get("model_ids", [])
    ]
    if not matches:
        return ""
    matches.sort(key=lambda comparison: (
        0 if len({MODEL_PRICING_BY_ID[mid]["provider"] for mid in comparison.get("model_ids", [])}) > 1 else 1,
        0 if comparison.get("template") == "editorial" else 1,
        comparison.get("title", ""),
    ))
    links = "".join(
        f'''<a href="/compare/{escape(comparison["slug"], quote=True)}/">
          <span>{escape(comparison["kicker"])}</span>
          <strong>{escape(comparison["title"])}</strong><b>↗</b>
        </a>'''
        for comparison in matches[:limit]
    )
    model = model_catalog_entry(model_id)
    return f'''<section class="model-compare-bridge shell" data-model-comparisons="{escape(model_id, quote=True)}">
      <div class="intel-section-head"><div><p class="eyebrow">COMPARE {escape(model["model"].upper())}</p><h2>Put this model in context.</h2></div><a href="/compare/">Open Compare Engine ↗</a></div>
      <div class="model-related-links">{links}</div>
    </section>'''


def render_catalog_model_page(model_id, items):
    model = model_catalog_entry(model_id)
    template = model.get("page_template")

    if template == "editorial-reference":
        if model_id == "gemini-3.7-flash":
            page = gemini_37_flash_reference_html()
        elif model_id == "gpt-6.1-sol":
            page = gpt_61_sol_reference_html()
        elif model_id == "claude-fable-5-1":
            page = claude_fable_51_reference_html(items)
        elif model_id == "gemini-3.8-flash":
            page = gemini_38_flash_reference_html(items)
        elif model_id == "grok-4.6":
            page = grok_46_reference_html()
        elif model_id == "grok-4.7":
            page = grok_47_reference_html()
        else:
            page = catalog_model_reference_html(model_id, items)
    elif template == "catalog-reference":
        page = catalog_model_reference_html(model_id, items)
    else:
        return None

    if "data-what-changed" not in page:
        page = inject_before_main_end(
            page,
            model_change_watch_html([model_id], f'{model["model"]}: what changed.')
        )
    if "data-model-history" not in page:
        page = inject_before_main_end(
            page,
            model_history_html([model_id], f'{model["model"]} verified history.')
        )
    if "data-model-comparisons" not in page:
        page = inject_before_main_end(page, model_comparison_links_html(model_id))
    if "data-model-evaluations" not in page:
        page = inject_before_main_end(page, evaluation_model_block_html(model_id))
    return page


def build_catalog_model_pages(items):
    rendered = 0
    for model in MODEL_PRICING_CATALOG["models"]:
        page = render_catalog_model_page(model["model_id"], items)
        if page is None:
            continue
        path = ROOT / model["sxf_url"].strip("/")
        path.mkdir(parents=True, exist_ok=True)
        (path / "index.html").write_text(page, encoding="utf-8")
        rendered += 1
    return rendered


